\begin{lemma}
\source{chabauty-coleman-bound-surfaces}
\notready\label{LemmaKSymm2} We have $K_{C^{(2)}}\equiv (2g-2)V-D/2$. Moreover, $V^2=1$, $(D.V)=2$, $D^2=4-4g$, and $c_1^2(C^{(2)})=(4g-9)(g-1)$.
